"""Independent offline worker schedules over authored tiny task repositories."""
import asyncio,hashlib,json,tempfile,time,sys
from dataclasses import replace
from pathlib import Path
from unittest.mock import patch
sys.path.insert(0,str(Path.cwd()))
from apps.qwen import coding_loop as worker
from apps.qwen import commands
from apps.qwen.context_tools import ContextTools
from devtools.core.paths import resolve_path
from devtools.models.interaction import InteractionSource,ModelResponse,ModelToolCall,ModelUsage,ModelTermination
from tests.apps.qwen.test_coding_loop import _tiny_task

O=Path(__file__).parent
SOURCE='src/devtools/sample.py'
OLD='def value():\n    return 0\n'
GOOD='def value() -> int:\n    return 1\n'
WRONG='def value() -> int:\n    return 2\n'
EXPECT={
 'prepared-success':'One independently specified correct proposal is accepted and restored.',
 'native-repair':'Read, incorrect edit, literal failed-oracle feedback, corrected edit; one repair and no hidden invocation.',
 'unobserved':'Literal correct source without native disclosure refuses before mutation.',
 'foreign':'Foreign response is archived and refuses before any Tool or edit.',
 'cancel-model':'Cancellation after invocation attempt remains unknown; no retry and original source restored.',
 'provider-failure':'One failed invocation; no retry or invented usage.',
 'unknown-source':'Unexpected changed bytes are preserved and require reconciliation.',
 'post-apply-failure':'Fault after real Git apply restores known candidate; no reexecution; candidate evidence survives.',
 'result-write-failure':'Final persistence failure propagates after source restoration; missing result is not a resumable checkpoint.',
 'native-shared-success':'Actual fixed checks/currentness can complete before restoration; no publication authority.',
 'post-accept-stage-failure':'Terminal host evidence failure must not present an unqualified accepted worker result.',
 'map-chain':'A whole-file anchor extending past the disclosed declaration range must refuse; orientation is not whole-file source.',
 'map-exact-chain':'Actual opt-in map orientation and exact declaration source ground an exact in-range subsequent edit.',
 'post-command-result-failure':'An entered fixed Git command followed by lost result is not retried; REFUSED alone is not proof of nonentry.',
 'cancel-validation':'Cancellation during candidate validation restores the known applied source and propagates without retry.',
 'directory-reuse':'Reusing a finished evidence directory refuses before another model entry.',
}

class Model:
 source=InteractionSource('independent-qwen-audit')
 def __init__(self,mode,task):self.mode=mode;self.task=task;self.requests=[];self.feedback=[]
 async def send(self,request):
  self.requests.append(request);n=len(self.requests)
  if self.mode=='cancel-model':raise asyncio.CancelledError()
  if self.mode=='provider-failure':raise RuntimeError('synthetic provider ambiguity, no usage supplied')
  if self.mode=='unknown-source':
   (self.root/SOURCE).write_text('UNKNOWN AUDIT BYTES\n',encoding='utf-8')
   raise RuntimeError('external change; stop')
  if request.prompt.role=='messages' and request.prompt.messages[-1].role=='tool':
   self.feedback.append(request.prompt.messages[-1].content)
  if self.mode in {'map-chain','map-exact-chain'} and n==1:
   name,args='repository_map',{'query':'value','start':0}
  elif self.mode in {'map-chain','map-exact-chain'} and n==2:
   v=json.loads(request.prompt.messages[-1].content)
   name,args='expand_source',{'unit':v['symbols'][0]['handle'],'to':'source'}
  elif self.mode=='post-command-result-failure':
   name,args='git_inspect',{'operation':'status','path':SOURCE}
  elif self.task.context_mode=='on-demand' and self.mode not in {'unobserved','foreign','map-chain','map-exact-chain'} and n==1:
   name,args='inspect_source',{'path':SOURCE,'start':0}
  elif self.mode in {'native-shared-success','post-accept-stage-failure'} and n==3:
   name,args='check_changes',{}
  else:
   name='replace_source' if self.task.context_mode=='on-demand' else 'propose_edit'
   args={'path':SOURCE,'old_text':WRONG if self.mode=='native-repair' and n==3 else OLD,'new_text':WRONG if self.mode=='native-repair' and n==2 else GOOD}
   if self.mode=='map-exact-chain':args.update(old_text=OLD.rstrip('\n'),new_text=GOOD.rstrip('\n'))
  return ModelResponse('Literal offline action',InteractionSource('foreign-audit') if self.mode=='foreign' else self.source,usage=ModelUsage(input_tokens=10,output_tokens=5),termination=ModelTermination.TOOL_CALL,tool_calls=(ModelToolCall(name,json.dumps(args),f'audit-{n}'),))

async def one(parent,mode):
 root=resolve_path(parent/mode).value;native=mode in {'native-repair','unobserved','foreign','map-chain','map-exact-chain','native-shared-success','post-accept-stage-failure','post-command-result-failure'}
 task=await _tiny_task(root,native=native)
 task=replace(task,maximum_calls=5 if native else 3,map_navigation=mode in {'map-chain','map-exact-chain'},command_tools=mode in {'native-shared-success','post-accept-stage-failure','post-command-result-failure'},quality_checks=mode in {'native-shared-success','post-accept-stage-failure'})
 model=Model(mode,task);model.root=root;folder=root/'.local/run';exception=None
 original_save=worker._save;original_apply=worker.apply_source_patches;original_check=worker.validate_workspace;original_command=commands._timed_command;effects=[];command_effects=[];validations=[]
 def save(path,value,**kwargs):
  if mode=='result-write-failure' and path.name=='result.json':raise OSError('synthetic final evidence unavailable')
  if mode=='post-accept-stage-failure' and path.name=='stage.json' and value.get('number')==3 and value.get('disposition')=='CONTEXT_RETURNED':raise OSError('synthetic stage persistence failure after acceptance')
  return original_save(path,value,**kwargs)
 async def apply(*args,**kwargs):
  await original_apply(*args,**kwargs);effects.append((root/SOURCE).read_text())
  if mode=='post-apply-failure':raise OSError('synthetic lost local apply acknowledgment')
 async def check(*args,**kwargs):
  validations.append(len(validations)+1)
  if mode=='cancel-validation' and len(validations)==2:raise asyncio.CancelledError()
  return await original_check(*args,**kwargs)
 async def command(*args,**kwargs):
  v=await original_command(*args,**kwargs)
  if mode=='post-command-result-failure' and args[1]=='git':
   command_effects.append(dict(argv=list(args[1:]),exit_code=v['exit_code']))
   raise OSError('synthetic command result lost after actual exit')
  return v
 result=None
 with patch.object(worker,'_save',save),patch.object(worker,'apply_source_patches',apply),patch.object(worker,'validate_workspace',check),patch.object(commands,'_timed_command',command):
  try:
   result=await worker.run_coding_task(root,folder,model,task=task,coordinated_edits=native,observed_edits=native,check_changes_before_completion=mode in {'native-shared-success','post-accept-stage-failure'})
  except BaseException as error:
   if not isinstance(error,(asyncio.CancelledError,OSError)):raise
   exception=dict(type=type(error).__name__,message=str(error))
 if result is None and (folder/'result.json').exists():result=json.loads((folder/'result.json').read_text())
 row=dict(case=mode,expected=EXPECT[mode],model_entries=len(model.requests),apply_effects=effects,command_effects=command_effects,exception=exception,current_source=(root/SOURCE).read_text(),result_file=(folder/'result.json').exists(),candidate=(folder/'final-source.py').read_text() if (folder/'final-source.py').exists() else None,result=result,feedback=model.feedback,task_sha256=task.definition_sha256)
 if mode=='directory-reuse':
  try:await worker.run_coding_task(root,folder,model,task=task)
  except FileExistsError:row['second_entry_refused']=True
  row['model_entries_after_reuse']=len(model.requests)
 return row

async def main():
 (O/'probe-expectations.json').write_text(json.dumps(EXPECT,indent=2)+'\n')
 started=time.perf_counter();rows=[]
 with tempfile.TemporaryDirectory(prefix='devtools-qwen-audit-') as raw:
  for mode in EXPECT:
   row=await one(Path(raw),mode);rows.append(row)
   (O/'probe-results.json').write_text(json.dumps(dict(seconds=time.perf_counter()-started,rows=rows),indent=2)+'\n',encoding='utf-8')
   print(json.dumps(dict(case=mode,accepted=(row['result'] or {}).get('accepted'),disposition=(row['result'] or {}).get('disposition'),calls=row['model_entries'],effects=len(row['apply_effects']),exception=row['exception'])),flush=True)
asyncio.run(main())
